using CP.ObjectPlanter;
using UnityEditor;
using UnityEngine;

namespace ProRoadMeshTools {

	/// <summary>
	/// ObjectPlanterLineが生成した結合メッシュを設定します。
	/// Sets up combined meshes generated by ObjectPlanterLine.
	/// </summary>
	internal static class ObjectPlanterLineUtility {

		/// <summary>
		/// 親オブジェクト直下のObjectPlanterLineで結合メッシュを有効化し、MeshColliderを追加します。
		/// Activates combined meshes and adds MeshCollider components for ObjectPlanterLine components directly under a parent object.
		/// </summary>
		internal static void ActivateCombinedMeshesAndAddColliders( GameObject _parent ) {
			if ( _parent == null ) return;

			Undo.IncrementCurrentGroup( );
			int undoGroup = Undo.GetCurrentGroup( );
			Undo.SetCurrentGroupName( "Activate ObjectPlanterLine Meshes and Add Colliders" );
			try {
				for ( int i = 0; i < _parent.transform.childCount; i++ ) {
					Transform child = _parent.transform.GetChild( i );
					ObjectPlanterLine line = child.GetComponent<ObjectPlanterLine>( );
					if ( line != null ) ActivateCombinedMeshAndAddColliderInternal( line );
				}
			}
			finally {
				Undo.CollapseUndoOperations( undoGroup );
			}
		}

		/// <summary>
		/// 1つのObjectPlanterLineで結合メッシュを有効化し、MeshColliderを追加します。
		/// Activates the combined mesh and adds a MeshCollider for one ObjectPlanterLine component.
		/// </summary>
		internal static void ActivateCombinedMeshAndAddCollider( ObjectPlanterLine _line ) {
			if ( _line == null || !_line.combineMeshes ) return;

			Undo.IncrementCurrentGroup( );
			int undoGroup = Undo.GetCurrentGroup( );
			Undo.SetCurrentGroupName( "Activate ObjectPlanterLine Mesh and Add Collider" );
			try {
				ActivateCombinedMeshAndAddColliderInternal( _line );
			}
			finally {
				Undo.CollapseUndoOperations( undoGroup );
			}
		}

		/// <summary>
		/// ObjectPlanterLineの結合メッシュだけを有効化し、MeshColliderを追加します。
		/// Activates only the ObjectPlanterLine combined mesh and adds a MeshCollider.
		/// </summary>
		private static void ActivateCombinedMeshAndAddColliderInternal( ObjectPlanterLine _line ) {
			if ( !_line.combineMeshes ) return;

			string meshName = $"{_line.gameObject.name}_0_0";
			Transform objectsParent = _line.transform.Find( "Objects" );
			if ( objectsParent == null ) return;

			for ( int i = 0; i < objectsParent.childCount; i++ ) {
				Transform child = objectsParent.GetChild( i );
				if ( child == null ) continue;

				bool isCombinedMesh = child.gameObject.name == meshName;
				if ( child.gameObject.activeSelf != isCombinedMesh ) {
					Undo.RecordObject( child.gameObject, "Set ObjectPlanterLine Mesh Active" );
					child.gameObject.SetActive( isCombinedMesh );
					PrefabUtility.RecordPrefabInstancePropertyModifications( child.gameObject );
					EditorUtility.SetDirty( child.gameObject );
				}
				if ( !isCombinedMesh ) continue;

				MeshCollider meshCollider = child.gameObject.GetComponent<MeshCollider>( );
				if ( meshCollider == null ) Undo.AddComponent<MeshCollider>( child.gameObject );

				Debug.Log( "Processed ObjectPlanterLine mesh: " + child.gameObject.name, child.gameObject );
			}
		}
	}
}
